import type { FurnitureLayout } from '../furnitureTypes';
import ta from './a';
import tc3 from './c3';
import tf1 from './f1';
import tj8 from './j8';
import tk3 from './k3';
import tl5 from './l5';
import tm5 from './m5';

export type { FurnitureLayout, FurnitureItem, FurnitureType } from '../furnitureTypes';

/** GENERATED by tools/trace/furniture.py. Illustrative model-flat furniture per traced unit type. */
const ALL: Record<string, FurnitureLayout> = { A: ta, C3: tc3, F1: tf1, J8: tj8, K3: tk3, L5: tl5, M5: tm5 };

/** Furniture layout for a unit type code (case-insensitive), or null if none was generated. */
export function furnitureFor(code: string): FurnitureLayout | null {
  return ALL[code.toUpperCase()] ?? null;
}
